def median(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate median value of this
    dataset.
    Median is the middle value of the dataset when sorted in ascending order.
    If the input dataset is even, average over the two middle numbers.
    >>> median([1.0, 2.0, 3.0, 4.0])
    2.5
    >>> median([2.0, 3.0, 6.0, 7.0])
    4.5
    """
    sorted_list = sorted(numbers)
    length = len(numbers)
    if length % 2 == 0:
        return round((sorted_list[length // 2 - 1] + sorted_list[length // 2]) / 2)
    else:
        return round(sorted_list[length // 2])


