def variance(numbers: List[float]) -> float:
    """ For a given list of input numbers, calculate Variance of this dataset.
    Variance is the average of squared differences between each element and a
    centerpoint (mean in this case):
    VARIANCE = average (x - x_mean)^2
    >>> variance([1.0, 2.0, 3.0, 4.0])
    1.5
    """
    if not numbers:
        return 0
    if len(numbers) == 1:
        return 0
    mean = sum(numbers) / len(numbers)
    squared_diffs = [((x - mean) ** 2) for x in numbers]
    return sum(squared_diffs) / len(numbers)


