    True
    >>> is_floating_point_number('3,5')
    True
    >>> is_floating_point_number('3')
    False
    """
    if "." in string or "," in string:
        if string.count('.') == 1 and string.count(',') == 0:
            return True
        elif string.count(',') == 1 and string.count('.') == 0:
            return True
        else:
