def get_number(n: str) -> float:
    """ Given a string that is in float, int, fraction or mixed format
    return the number.
    >>> get_number("3")
    3.0
    >>> get_number("11.57")
    11.57
    >>> get_number("4 5/8")
    4.625
    >>> get_number("0.5567")
    0.5567
    >>> get_number("275.0000000000000245")
    275.0
    >>> get_number("4e-3")
    0.004
    """
    if n == '0' or n == '0.0':
        return 0.0
    elif '.' not in n:
        try:
            return int(n)
        except ValueError:
            return float(n)
    else:
        try:
            return float(n)
        except ValueError:
            return float(n.replace('e-', 'e +'))

